const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/users/bulk_update_project_details',
  headers: {
    Authorization: 'Bearer REPLACE_BEARER_TOKEN',
    'content-type': 'application/json'
  },
  body: {
    users: [
      {
        user_id: '12345',
        project_id: '23456',
        permission_template_id: '34567',
        project_role_ids: ['45678']
      }
    ]
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/users/bulk_update_project_details"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
    Content = new StringContent("{\"users\":[{\"user_id\":\"12345\",\"project_id\":\"23456\",\"permission_template_id\":\"34567\",\"project_role_ids\":[\"45678\"]}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

